Here is the commit message:
fuse: reject fuse_notify() pagecache ops on directories

The operations FUSE_NOTIFY_STORE and FUSE_NOTIFY_RETRIEVE allow the
FUSE daemon to actively write/read pagecache contents.

For directories with FOPEN_CACHE_DIR, the pagecache is used as
kernel-internal cache storage, and userspace is not supposed to have
direct access to this cache - in particular, fuse_parse_cache() will hit
WARN_ON() if the cache contains bogus data.

Reject FUSE_NOTIFY_STORE and FUSE_NOTIFY_RETRIEVE on anything other than
regular files with -EINVAL.

Fixes: 5d7bc7e8680c ("fuse: allow using readdir cache")
Cc: stable@vger.kernel.org
Signed-off-by: Jann Horn <jannh@google.com>
Link: https://patch.msgid.link/20260519-fuse-dir-pagecache-v2-1-5428fa48e175@google.com
Acked-by: Miklos Szeredi <mszeredi@redhat.com>
Signed-off-by: Christian Brauner (Amutable) <brauner@kernel.org>

Here is the root cause:
The fuse notify store and retrieve operations did not restrict operations to regular files, allowing them on directories which use pagecache as internal cache, leading to potential corruption and WARN_ON.

Here is the patch:

 static int fuse_notify_store(struct fuse_conn *fc, unsigned int size,
 			     struct fuse_copy_state *cs)
 {
 	struct fuse_notify_store_out outarg;
 	struct inode *inode;
 	struct address_space *mapping;
 	u64 nodeid;
 	int err;
 	unsigned int num;
 	loff_t file_size;
 	loff_t pos;
 	loff_t end;

 	if (size < sizeof(outarg))
 		return -EINVAL;

 	err = fuse_copy_one(cs, &outarg, sizeof(outarg));
 	if (err)
 		return err;

 	if (size - sizeof(outarg) != outarg.size)
 		return -EINVAL;

 	if (outarg.offset >= MAX_LFS_FILESIZE)
 		return -EINVAL;

 	nodeid = outarg.nodeid;
 	pos = outarg.offset;
 	num = min(outarg.size, MAX_LFS_FILESIZE - pos);

 	down_read(&fc->killsb);

 	err = -ENOENT;
 	inode = fuse_ilookup(fc, nodeid,  NULL);
 	if (!inode)
 		goto out_up_killsb;
+	if (!S_ISREG(inode->i_mode)) {
+		err = -EINVAL;
+		goto out_iput;
+	}

 	mapping = inode->i_mapping;
 	file_size = i_size_read(inode);
 	end = pos + num;
 	if (end > file_size) {
 		file_size = end;
 		fuse_write_update_attr(inode, file_size, num);
 	}

 	while (num) {
 		struct folio *folio;
 		unsigned int folio_offset;
 		unsigned int nr_bytes;
 		pgoff_t index = pos >> PAGE_SHIFT;

 		folio = filemap_grab_folio(mapping, index);
 		err = PTR_ERR(folio);
 		if (IS_ERR(folio))
 			goto out_iput;

 		folio_offset = offset_in_folio(folio, pos);
 		nr_bytes = min(num, folio_size(folio) - folio_offset);

 		err = fuse_copy_folio(cs, &folio, folio_offset, nr_bytes, 0);
 		if (!folio_test_uptodate(folio) && !err && folio_offset == 0 &&
 		    (nr_bytes == folio_size(folio) || file_size == end)) {
 			folio_zero_segment(folio, nr_bytes, folio_size(folio));
 			folio_mark_uptodate(folio);
 		}
 		folio_unlock(folio);
 		folio_put(folio);

 		if (err)
 			goto out_iput;

 		pos += nr_bytes;
 		num -= nr_bytes;
 	}

 	err = 0;

 out_iput:
 	iput(inode);
 out_up_killsb:
 	up_read(&fc->killsb);
 	return err;
 }


 static int fuse_notify_retrieve(struct fuse_conn *fc, unsigned int size,
 				struct fuse_copy_state *cs)
 {
 	struct fuse_notify_retrieve_out outarg;
 	struct fuse_mount *fm;
 	struct inode *inode;
 	u64 nodeid;
 	int err;

 	if (size != sizeof(outarg))
 		return -EINVAL;

 	err = fuse_copy_one(cs, &outarg, sizeof(outarg));
 	if (err)
 		return err;

 	fuse_copy_finish(cs);

 	if (outarg.offset >= MAX_LFS_FILESIZE)
 		return -EINVAL;

 	down_read(&fc->killsb);
 	err = -ENOENT;
 	nodeid = outarg.nodeid;

 	inode = fuse_ilookup(fc, nodeid, &fm);
 	if (inode) {
-		err = fuse_retrieve(fm, inode, &outarg);
+		if (!S_ISREG(inode->i_mode))
+			err = -EINVAL;
+		else
+			err = fuse_retrieve(fm, inode, &outarg);
 		iput(inode);
 	}
 	up_read(&fc->killsb);

 	return err;
 }



